var app = builder.Build();

app.MapGet("/hello", () => new { message = "Hello CSharp" });
app.MapGet("/lessons/{id:int}", (int id) => new { id, title = $"Lesson {id}" });

app.Run("http://127.0.0.1:5080");     GET /lessons/3が来たとき、/lessons/{id:int}という経路と対応させます。    図解  /lessons/3の3をint idへ渡す      1   要求  GET /lessons/3     2   経路に一致  /lessons/{id:int}     3   引

この最小例はTitleの空白と元の文字数を調べ、Trimしたタイトルを200で返すプレビューです。作成・保存するAPIとは区別します。    図解  /previewは確認結果を返すだけで保存しない      1   受け取る  CreateTaskRequest.Title     2   検証  空白だけ / 元の長さが100を超えるなら400     3   整える  Title.Trim()     4   返す  200で確認結果を返す。保存はしない       このコードの文字数判定はTrimより前です。後の作成例では、正規化した値を検証し、その同じ値を保存する流れを確認します。   想定出力  POST /preview {"title":"C#"} → 200
POST /preview {"title":" "} → 400  処理順   JSONのtitleをCreateTaskRequestへ受け取る。  空白や長すぎる入力を拒否し400を返す。  正常な場合は前後空白を除いたタイトルを200で返す。今回は保存しないプレビュー。     保存の前に検証を終える   結果をステータスで伝える  取得成功は200、新規作成成功は201、入力不正は400、対象なしは404など、HTTP上の意味に合わせて返します。すべて200で本文だけにerrorを入れると、呼び出し側や監視側が成功と失敗を見分けにくくなります。201では作成した対象のURLをLocationとして返すことができます。    正規化した値を検証してその値を保存する  タイトルの前後空白を除く仕様なら、Trimした値に対して必須と長さを検証し、その同じ値を保存します。元文字列で長さを検査した後、別の加工値を保存すると、判断対象と保存対象がずれます。大小文字を同一視するか、連続空白をまとめるかはデータの意味に応じて決めます。  string.LengthはUTF-16コード単位数です。絵文字などを人が見た文字数と同じに数える仕様ではありません。この例の上限は.Lengthに基づきます。表示上の文字数が要件になる場合は、StringInfoなどで文字のまとまりを数える方法を検討します。正規化は入力を勝手に改変する万能な処理ではなく、合意した規則です。   前後の空白を取り除いて保存する仕様なら、その結果の値を基準に検証します。    図解  検証した値と保存する値を一致させる      1   元の入力  "  学習  "     2   正規化  Trim → "学習"     3   検証  正規化後の必須・長さを確認     4   保存  確認した"学習"を保存       元の入力を検証したのに別の値を保存したり、その逆になったりしないようにします。何文字を許すかも、正規化後の値に対する仕様として決めます。      タイトルを検証して作成し、GETで参照する      csharp  Copy  折り返し    using System.Collections.Concurrent;
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();
var items = new ConcurrentDictionary<Guid, Item>();
app.MapPost("/items", (CreateItem input) =>
{
    string title = input.Title?.Trim() ?? "";
    if (title.Length is < 1 or > 40)
        return Results.ValidationProblem(new Dictionary<string, string[]> { ["title"] = new[] { "1〜40文字で入力してください" } });
    var item = new Item(Guid.NewGuid(), title);
    if (!items.TryAdd(item.Id, item)) return Results.Conflict();
    return Results.Created($"/items/{item.Id}", item);
});
app.MapGet("/items/{id:guid}", (Guid id) => items.TryGetValue(id, out var item) ? Results.Ok(item) : Results.NotFound());
app.Run("http://127.0.0.1:5080");
public record CreateItem(string? Title);
public record Item(Guid Id, string Title);    出力  POST /items 本文{"title":" C# "} → 201、title="C#"、idは生成されたGUID
