static IResult GetLesson(int id)
{
    if (id is < 1 or > 32)
        return Results.NotFound(new { error = "レッスンがありません" });
    return Results.Ok(new { id, title = $"Lesson {id}" });
}     このAPIは/lessons/{id:int}で整数を受け取り、1から32の範囲だけ成功にしています。    図解  同じ404でも、どこで判定したかを分ける      /lessons/0  範囲外 → 404    /lessons/1  範囲内 → 200    /lessons/32  範囲内 → 200    /lessons/33  範囲外 → 404    /lessons/abc  経路不一致 → 404      0や33はハンドラー内の範囲チェックで404です。abcはintの経路制約に一致しないため、そのハンドラーへ到達しません。境界と形式を分けて確認します。   想定出力  GET /lessons/1 → 200
